function procesarDeudasServicio(nodeName) {
  try {
    const node = $(nodeName);
    if (!node || !node.all) return null;

    const items = node.all().map(item => item.json).filter(j => j && (j.MontoaPagar != null || j.SubtotalItem != null));
    if (items.length === 0) return null;

    const hoy = new Date();
    let totalMonto = 0;
    const listaTarjetas = [];

    items.forEach(item => {
      // Tomamos MontoaPagar si existe, o SubtotalItem como alternativa
      const monto = parseFloat(item.MontoaPagar || item.SubtotalItem) || 0;
      totalMonto += monto;

      // Código de usuario y domicilio
      const codigoUsuario = item.Codigo || item.Usuario || item.codigo || "S/D";
      const domicilio = item.Domicilio ? item.Domicilio.trim() : "";
      const itemFacturado = item.ItemFacturado ? " - " + item.ItemFacturado : "";

      // Sepelio incluido en la factura de otro servicio (H-15)
      const perteneceA = item.ServicioComprobante
        ? "\n🔗 Pertenece a la factura de " + item.ServicioComprobante + " (ya incluido en su importe)"
        : "";

      // Evaluar si está vencido
      let estadoVencimiento = "🔴 VENCIDO";
      if (item.FechaVencimientoFormateada) {
        const partes = item.FechaVencimientoFormateada.split('/');
        if (partes.length === 3) {
          const fechaVenc = new Date(partes[2], partes[1] - 1, partes[0]);
          if (fechaVenc >= hoy) {
            estadoVencimiento = "🟢 A VENCER";
          }
        }
      }

      // Formato del monto
      const montoFormateado = monto.toLocaleString('es-AR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

      // Armado de tarjeta
      let tarjeta = "";
      if (domicilio) {
        tarjeta += "📍 " + domicilio + "\n";
      }
      tarjeta += "👤 Usuario: " + codigoUsuario + "\n" +
                 "📅 Periodo: Mes " + item.Mes + "/" + item.Anio + itemFacturado + perteneceA + "\n" +
                 "💵 Importe: $" + montoFormateado + "\n" +
                 "📆 Vencimiento: " + (item.FechaVencimientoFormateada || "A confirmar") + " (" + estadoVencimiento + ")";

      listaTarjetas.push(tarjeta);
    });

    return {
      montoTotal: Math.round(totalMonto * 100) / 100,
      detalleFormateado: listaTarjetas.join("\n─────────────────\n"),
      cantidadFacturas: items.length
    };
  } catch (e) {
    return null;
  }
}

// Ejecución por nodo
const energia = procesarDeudasServicio("Deuda_Servicio Energia");
const agua = procesarDeudasServicio("Deuda_Servicio_Agua");
const internet = procesarDeudasServicio("Deuda_Servicio_Internet");
const sepelio = procesarDeudasServicio("Deuda_Servicio_Sepelio");
const municipalidad = procesarDeudasServicio("Deuda_Servicio_Municipalidad");

// Retorno consolidado para Typebot
return [{
  json: {
    tiene_deuda: energia !== null || agua !== null || internet !== null || sepelio !== null || municipalidad !== null,

    // Energía
    tiene_energia: energia !== null,
    monto_energia: energia ? energia.montoTotal : null,
    detalle_energia: energia ? energia.detalleFormateado : null,

    // Agua
    tiene_agua: agua !== null,
    monto_agua: agua ? agua.montoTotal : null,
    detalle_agua: agua ? agua.detalleFormateado : null,

    // Internet
    tiene_internet: internet !== null,
    monto_internet: internet ? internet.montoTotal : null,
    detalle_internet: internet ? internet.detalleFormateado : null,

    // Sepelio 🕊️ (Mapeado con soporte para SubtotalItem y descripción de ítem)
    tiene_sepelio: sepelio !== null,
    monto_sepelio: sepelio ? sepelio.montoTotal : null,
    detalle_sepelio: sepelio ? sepelio.detalleFormateado : null,

    // Municipalidad 🏛️
    tiene_municipalidad: municipalidad !== null,
    monto_municipalidad: municipalidad ? municipalidad.montoTotal : null,
    detalle_municipalidad: municipalidad ?  municipalidad.detalleFormateado : null
  }
}];

const items = $input.all();

if (!items || items.length === 0 || !items[0].json.SubtotalGeneral) {
  return [{
    json: {
      tiene_deuda: false,
      gravado: "$ 0,00",
      no_gravado: "$ 0,00",
      iva: "$ 0,00",
      total: "$ 0,00"
    }
  }];
}

const data = items[0].json;
const fmt = (v) => new Intl.NumberFormat('es-AR', { style: 'currency', currency: 'ARS' }).format(Number(v) || 0);

return [{
  json: {
    tiene_deuda: true,
    gravado: fmt(data.TotalGravado),
    no_gravado: fmt(data.TotalNoGravado),
    iva: fmt(data.TotalIVA),
    total: fmt(data.SubtotalGeneral)
  }
}];

// Leemos los datos enviados por el webhook
const webhookData = $('Validar_Entrada_factura').first().json.body;
const cuenta = webhookData.cuenta || '';
const dniIngresado = webhookData.dni || '';

// Obtenemos los valores procesados por la query SQL
const itemSql = $input.first()?.json;
const identificador = itemSql?.Identificador || dniIngresado;
const tipoDoc = itemSql?.TipoDoc || 'dni';

// Construimos la URL apuntando directamente a list.php
let urlFinal = `https://comprobantes.cuecca.com.ar/list.php?cuenta=${encodeURIComponent(cuenta)}`;

if (tipoDoc === 'cuit') {
  urlFinal += `&cuit=${encodeURIComponent(identificador)}`;
} else {
  urlFinal += `&dni=${encodeURIComponent(identificador)}`;
}

return [{
  json: {
    url_factura: urlFinal
  }
}];

const inputData = $input.first().json;

// 1. Obtenemos el texto bruto del body
let rawBody = '';
if (inputData.query && inputData.query.body) {
  rawBody = typeof inputData.query.body === 'string' ? inputData.query.body : JSON.stringify(inputData.query.body);
} else if (inputData.body) {
  rawBody = typeof inputData.body === 'string' ? inputData.body : JSON.stringify(inputData.body);
}

let socio = '';
let codigo = '';
let domicilio = '';

// 2. Intentamos parsear como JSON normal
try {
  const parsed = JSON.parse(rawBody);
  socio = parsed.socio || '';
  codigo = parsed.codigo || parsed.user_id || '';
  domicilio = parsed.domicilio || '';
} catch (e) {
  // 3. Si el JSON viene mal construido/sin comas, extraemos los datos con Expresiones Regulares (Regex)
  const socioMatch = rawBody.match(/"socio"\s*:\s*"([^"]+)"/);
  const codigoMatch = rawBody.match(/"codigo"\s*:\s*"([^"]+)"/) || rawBody.match(/"user_id"\s*:\s*"([^"]+)"/);
  const domMatch = rawBody.match(/"domicilio"\s*:\s*"([^"]+)"/);

  if (socioMatch) socio = socioMatch[1];
  if (codigoMatch) codigo = codigoMatch[1];
  if (domMatch) domicilio = domMatch[1];
}

// 4. Limpiamos los paréntesis del domicilio
if (typeof domicilio === 'string' && domicilio.includes('(')) {
  domicilio = domicilio.split('(')[0];
}

// 5. Validación (H-01)
const socioLimpio = String(socio).trim().replace(/[\s.\-]/g, '');
if (!/^\d{1,15}$/.test(socioLimpio)) {
  throw new Error('Entrada inválida en el campo "socio"');
}
let domicilioSeguro = String(domicilio).trim().toUpperCase().slice(0, 200);
domicilioSeguro = domicilioSeguro.replace(/'/g, "''");

return [{
  json: {
    socio: socioLimpio,
    codigo: String(codigo).trim(),
    domicilio_limpio: domicilioSeguro
  }
}];

const items = $input.all().map(item => item.json).filter(j => j && j.Nombre);

let resultado = {
  encontrado: false,
  nombre: "",
  detalle_energia: "No se registran consumos recientes de Energía.",
  detalle_agua: "No se registran consumos recientes de Agua."
};

if (items.length > 0) {
  resultado.encontrado = true;
  resultado.nombre = items[0].Nombre;

  // Estructuras para agrupar por suministro único (combinando Domicilio y Medidor)
  const suministrosEnergia = {};
  const suministrosAgua = {};

  items.forEach(item => {
    const servicio = (item.Servicio || '').toLowerCase();
    const domicilio = item.Domicilio ? item.Domicilio.trim() : "S/D";
    const medidor = item.Medidor || "S/N";
    const consumo = item.Consumo ?? 0;

    // Clave única para separar cada propiedad/medidor del socio
    const key = `${domicilio}_${medidor}`;

    if (servicio === 'energia') {
      const textoPeriodo = `📅 Mes ${item.Mes}/${item.Anio}: *${consumo} kWh*`;
      if (!suministrosEnergia[key]) {
        suministrosEnergia[key] = { domicilio, medidor, registros: [] };
      }
      suministrosEnergia[key].registros.push(textoPeriodo);
    } else if (servicio === 'agua') {
      const textoPeriodo = `📅 Mes ${item.Mes}/${item.Anio}: *${consumo} m³*`;
      if (!suministrosAgua[key]) {
        suministrosAgua[key] = { domicilio, medidor, registros: [] };
      }
      suministrosAgua[key].registros.push(textoPeriodo);
    }
  });

  // Formatear bloques de Energía diferenciando domicilios
  const arrayEnergia = Object.values(suministrosEnergia);
  if (arrayEnergia.length > 0) {
    let textosEnergia = arrayEnergia.map(s => {
      return `📍 *${s.domicilio}*\n🔢 Medidor: ${s.medidor}\n` + s.registros.join("\n");
    });
    resultado.detalle_energia = "💡 *CONSUMOS DE ENERGÍA*\n\n" + textosEnergia.join("\n\n─────────────────\n\n");
  }

  // Formatear bloques de Agua diferenciando domicilios
  const arrayAgua = Object.values(suministrosAgua);
  if (arrayAgua.length > 0) {
    let textosAgua = arrayAgua.map(s => {
      return `📍 *${s.domicilio}*\n🔢 Medidor: ${s.medidor}\n` + s.registros.join("\n");
    });
    resultado.detalle_agua = "💧 *CONSUMOS DE AGUA*\n\n" + textosAgua.join("\n\n─────────────────\n\n");
  }
}

return [{ json: resultado }];

try {
  const items = $input.all().map(item => item.json).filter(j => j && j.MontoaPagar != null);

  // Sin deuda: monto en null para que Typebot vaya a "No posee deudas" (H-16)
  if (items.length === 0) {
    return [{ json: { tiene_deuda: false, monto_total_general: 0, monto_total_formateado: null, detalle_por_periodo: null } }];
  }

  const hoy = new Date();

  const serviciosMap = {
    "Energia": { items: [], emoji: "💡", titulo: "ENERGÍA" },
    "Agua": { items: [], emoji: "💧", titulo: "AGUA" },
    "Internet": { items: [], emoji: "🌐", titulo: "INTERNET" },
    "Sepelio": { items: [], emoji: "🕊️", titulo: "SECTOR SEPELIO" },
    "Municipalidad": { items: [], emoji: "🏛️", titulo: "TASA MUNICIPAL" }
  };

  let totalGeneral = 0;
  const periodosMap = {};

  items.forEach(item => {
    const monto = parseFloat(item.MontoaPagar) || 0;
    totalGeneral += monto;

    const servicioNombre = item.Servicio;
    if (!serviciosMap[servicioNombre]) return;

    const codigoUsuario = item.Usuario || "S/D";
    const domicilio = item.Domicilio ? item.Domicilio.trim() : "";
    const itemFacturado = item.ItemFacturado ? " - " + item.ItemFacturado : "";
    const periodoKey = `${item.Mes}/${item.Anio}`;

    if (!periodosMap[periodoKey]) {
      periodosMap[periodoKey] = {
        orden: Number(item.Anio) * 100 + Number(item.Mes),   // para ordenar cronológicamente
        montoTotalPeriodo: 0,
        conceptos: []
      };
    }
    periodosMap[periodoKey].montoTotalPeriodo += monto;
    periodosMap[periodoKey].conceptos.push(`${serviciosMap[servicioNombre].emoji} ${servicioNombre} (${domicilio || 'S/D'}) - Mes ${periodoKey}: $${monto.toLocaleString('es-AR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`);

    let estadoVencimiento = "🔴 VENCIDO";
    if (item.FechaVencimientoFormateada) {
      const partes = item.FechaVencimientoFormateada.split('/');
      if (partes.length === 3) {
        const fechaVenc = new Date(partes[2], partes[1] - 1, partes[0]);
        if (fechaVenc >= hoy) {
          estadoVencimiento = "🟢 A VENCER";
        }
      }
    }

    const montoFormateado = monto.toLocaleString('es-AR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

    let tarjeta = "";
    if (domicilio) {
      tarjeta += "📍 " + domicilio + " | ";
    }
    tarjeta += "Usuario: " + codigoUsuario + " | Período: " + periodoKey + itemFacturado + " | Importe: $" + montoFormateado + " (" + estadoVencimiento + ")";

    serviciosMap[servicioNombre].items.push({
      monto: monto,
      tarjeta: tarjeta
    });
  });

  function procesarBloqueServicio(servData) {
    if (servData.items.length === 0) return { montoTotal: 0, detalleFormateado: null };

    const montoTotalServicio = servData.items.reduce((acc, curr) => acc + curr.monto, 0);
    const listaTarjetas = servData.items.map(i => i.tarjeta);
    const detalleFormateado = servData.emoji + " *" + servData.titulo + "*\n" + listaTarjetas.join("\n");

    return {
      montoTotal: Math.round(montoTotalServicio * 100) / 100,
      detalleFormateado: detalleFormateado
    };
  }

  const listaPeriodosTexto = [];
  Object.keys(periodosMap)
    .sort((a, b) => periodosMap[a].orden - periodosMap[b].orden)   // cronológico, no alfabético
    .forEach(periodo => {
      const pData = periodosMap[periodo];
      const subtotalFormateado = pData.montoTotalPeriodo.toLocaleString('es-AR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
      listaPeriodosTexto.push(`📅 *Período ${periodo}*: $${subtotalFormateado}\n` + pData.conceptos.join("\n"));
    });

  const detallePorPeriodoFormateado = listaPeriodosTexto.join("\n\n─────────────────\n\n");

  const resEnergia = procesarBloqueServicio(serviciosMap["Energia"]);
  const resAgua = procesarBloqueServicio(serviciosMap["Agua"]);
  const resInternet = procesarBloqueServicio(serviciosMap["Internet"]);
  const resSepelio = procesarBloqueServicio(serviciosMap["Sepelio"]);
  const resMunicipalidad = procesarBloqueServicio(serviciosMap["Municipalidad"]);

  const deudaTotalGeneralRedondeada = Math.round(totalGeneral * 100) / 100;
  const deudaTotalFormateada = deudaTotalGeneralRedondeada.toLocaleString('es-AR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

  return [{
    json: {
      tiene_deuda: items.length > 0,
      monto_total_general: deudaTotalGeneralRedondeada,
      monto_total_formateado: "$" + deudaTotalFormateada,
      detalle_por_periodo: detallePorPeriodoFormateado,

      tiene_energia: resEnergia.detalleFormateado !== null,
      monto_energia: resEnergia.montoTotal,
      detalle_energia: resEnergia.detalleFormateado,

      tiene_agua: resAgua.detalleFormateado !== null,
      monto_agua: resAgua.montoTotal,
      detalle_agua: resAgua.detalleFormateado,

      tiene_internet: resInternet.detalleFormateado !== null,
      monto_internet: resInternet.montoTotal,
      detalle_internet: resInternet.detalleFormateado,

      tiene_sepelio: resSepelio.detalleFormateado !== null,
      monto_sepelio: resSepelio.montoTotal,
      detalle_sepelio: resSepelio.detalleFormateado,

      tiene_municipalidad: resMunicipalidad.detalleFormateado !== null,
      monto_municipalidad: resMunicipalidad.montoTotal,
      detalle_municipalidad: resMunicipalidad.detalleFormateado
    }
  }];

} catch (e) {
  return [{
    json: {
      tiene_deuda: false,
      monto_total_general: 0,
      monto_total_formateado: null,
      detalle_por_periodo: null
    }
  }];
}

